"use client";

import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import AppShell from "@/components/Navbar";
import { api } from "@/lib/api";
import { me, type AuthUser } from "@/lib/auth";

interface DashboardTotalsResponse {
  success: boolean;
  data: {
    users: number;
    active_users: number;
    pending_requests: number;
    approved_requests: number;
    confirmed_bookings: number;
    notifications: number;
  };
}

interface RequestsResponse {
  success: boolean;
  data: Array<{
    id: number;
    status: "Pending" | "Approved" | "Rejected";
    preferred_day_of_week?: string;
    preferred_start_time?: string;
    preferred_end_time?: string;
    expected_students?: number;
    section?: { expected_students?: number };
    room?: { room_number?: string; capacity?: number };
    course?: { course_code?: string; course_title?: string };
    instructor?: { first_name?: string; last_name?: string };
  }>;
}

interface FacultyLoadResponse {
  success: boolean;
  data: Array<{
    instructor?: { first_name?: string; last_name?: string };
    max_units: number;
    assigned_units: number;
  }>;
}

interface AuditResponse {
  success: boolean;
  data: Array<{
    id: number;
    action: string;
    target_table: string;
    target_id: number | null;
    performed_at: string;
  }>;
}

function StatusBadge({ status }: { status: "Pending" | "Approved" | "Rejected" }) {
  const map = {
    Pending: { bg: "#fff8e6", color: "#92620a" },
    Approved: { bg: "#e8f5ee", color: "#1a7a3c" },
    Rejected: { bg: "#fdecea", color: "#d93025" },
  };
  const s = map[status];
  return <span className="px-2 py-0.5 rounded-full text-[11px] font-semibold" style={{ background: s.bg, color: s.color }}>{status}</span>;
}

export default function AdminDashboard() {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [totals, setTotals] = useState<DashboardTotalsResponse["data"] | null>(null);
  const [requests, setRequests] = useState<RequestsResponse["data"]>([]);
  const [faculty, setFaculty] = useState<FacultyLoadResponse["data"]>([]);
  const [audit, setAudit] = useState<AuditResponse["data"]>([]);

  useEffect(() => {
    (async () => {
      try {
        setLoading(true);
        setError(null);
        const [meData, d, r, f, a] = await Promise.all([
          me(),
          api.get<DashboardTotalsResponse>("/admin/dashboard"),
          api.get<RequestsResponse>("/admin/requests?per_page=6"),
          api.get<FacultyLoadResponse>("/admin/faculty-load?per_page=5"),
          api.get<AuditResponse>("/admin/audit-log?per_page=5"),
        ]);
        setUser(meData);
        setTotals(d.data);
        setRequests(r.data ?? []);
        setFaculty(f.data ?? []);
        setAudit(a.data ?? []);
      } catch (e) {
        setError(e instanceof Error ? e.message : "Failed to load admin dashboard.");
      } finally {
        setLoading(false);
      }
    })();
  }, []);

  const pendingRequests = useMemo(() => requests.filter((r) => r.status === "Pending"), [requests]);

  return (
    <AppShell role="admin" userName={user ? `${user.first_name} ${user.last_name}` : "Admin"} pageTitle="Dashboard">
      <div className="space-y-5">
        <div>
          <h1 className="text-[20px] font-bold">Admin Dashboard</h1>
          <p className="text-[13px]" style={{ color: "var(--color-text-muted)" }}>{loading ? "Loading..." : "Live system overview"}</p>
        </div>

        {error && <div className="rounded-lg border px-3 py-2 text-[12px]" style={{ borderColor: "#fecaca", background: "#fff1f2", color: "#9f1239" }}>{error}</div>}

        <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
          <StatCard label="Users" value={totals?.users ?? 0} sub={`${totals?.active_users ?? 0} active`} href="/admin/users" />
          <StatCard label="Pending Requests" value={totals?.pending_requests ?? 0} sub={`${totals?.approved_requests ?? 0} approved`} href="/admin/requests" />
          <StatCard label="Confirmed Bookings" value={totals?.confirmed_bookings ?? 0} sub="Active schedules" href="/admin/schedule" />
          <StatCard label="Unread Notifications" value={totals?.notifications ?? 0} sub="Needs attention" href="/notifications" />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-5">
          <div className="lg:col-span-2 card">
            <div className="card-body pb-2 flex items-center justify-between">
              <h2 className="text-[14px] font-semibold">Recent Room Requests</h2>
              <Link href="/admin/requests" className="text-[12px]" style={{ color: "var(--color-primary-light)" }}>View all</Link>
            </div>
            <div className="overflow-x-auto">
              <table className="table-base">
                <thead><tr><th>ID</th><th>Instructor</th><th>Subject</th><th>Room</th><th>Time</th><th>Status</th></tr></thead>
                <tbody>
                  {requests.map((r) => (
                    <tr key={r.id}>
                      <td>#{r.id}</td>
                      <td>{r.instructor ? `${r.instructor.first_name ?? ""} ${r.instructor.last_name ?? ""}`.trim() : "N/A"}</td>
                      <td>{r.course?.course_code ?? "N/A"}</td>
                      <td>{r.room?.room_number ?? "TBA"}</td>
                      <td>{r.preferred_day_of_week ?? ""} {r.preferred_start_time?.slice(0, 5)}-{r.preferred_end_time?.slice(0, 5)}</td>
                      <td><StatusBadge status={r.status} /></td>
                    </tr>
                  ))}
                  {!loading && requests.length === 0 && <tr><td colSpan={6} className="text-center text-[12px]">No requests found.</td></tr>}
                </tbody>
              </table>
            </div>
          </div>

          <div className="card card-body">
            <div className="flex items-center justify-between mb-3">
              <h2 className="text-[14px] font-semibold">Faculty Load</h2>
              <Link href="/admin/faculty-load" className="text-[12px]" style={{ color: "var(--color-primary-light)" }}>View all</Link>
            </div>
            <div className="space-y-3">
              {faculty.map((f, i) => {
                const pct = f.max_units > 0 ? Math.round((f.assigned_units / f.max_units) * 100) : 0;
                return (
                  <div key={i}>
                    <div className="flex justify-between text-[12px]">
                      <span>{f.instructor ? `${f.instructor.first_name ?? ""} ${f.instructor.last_name ?? ""}`.trim() : "N/A"}</span>
                      <span>{f.assigned_units}/{f.max_units}u</span>
                    </div>
                    <div className="h-1.5 rounded-full mt-1" style={{ background: "var(--color-surface-2)" }}>
                      <div className="h-1.5 rounded-full" style={{ width: `${Math.min(pct, 100)}%`, background: pct >= 100 ? "#d93025" : "#22a050" }} />
                    </div>
                  </div>
                );
              })}
              {!loading && faculty.length === 0 && <p className="text-[12px]" style={{ color: "var(--color-text-muted)" }}>No faculty load records.</p>}
            </div>
          </div>
        </div>

        <div className="card">
          <div className="card-body pb-2 flex items-center justify-between">
            <h2 className="text-[14px] font-semibold">Recent Audit Activity</h2>
            <Link href="/admin/audit-log" className="text-[12px]" style={{ color: "var(--color-primary-light)" }}>View all</Link>
          </div>
          <div className="overflow-x-auto">
            <table className="table-base">
              <thead><tr><th>ID</th><th>Action</th><th>Target</th><th>Time</th></tr></thead>
              <tbody>
                {audit.map((a) => (
                  <tr key={a.id}>
                    <td>#{a.id}</td>
                    <td>{a.action}</td>
                    <td>{a.target_table}{a.target_id ? ` #${a.target_id}` : ""}</td>
                    <td>{new Date(a.performed_at).toLocaleString("en-US")}</td>
                  </tr>
                ))}
                {!loading && audit.length === 0 && <tr><td colSpan={4} className="text-center text-[12px]">No audit records.</td></tr>}
              </tbody>
            </table>
          </div>
        </div>

        {!loading && pendingRequests.length > 0 && (
          <div className="rounded-xl border px-4 py-3 text-[12px]" style={{ borderColor: "rgba(240,165,0,.25)", background: "#fff8e6", color: "#92620a" }}>
            There are {pendingRequests.length} pending requests in the latest batch that still need review.
          </div>
        )}
      </div>
    </AppShell>
  );
}

function StatCard({ label, value, sub, href }: { label: string; value: number; sub: string; href: string }) {
  return (
    <Link href={href} className="card card-body block">
      <p className="text-[12px]" style={{ color: "var(--color-text-muted)" }}>{label}</p>
      <p className="text-[24px] font-bold">{value}</p>
      <p className="text-[11px]" style={{ color: "var(--color-text-muted)" }}>{sub}</p>
    </Link>
  );
}
